package com.bank.vt;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class SemaphoreGateTest {

    @Test void semaphoreLimitsConcurrentAccess() throws Exception {
        Semaphore permits = new Semaphore(5);  // max 5 concurrent
        AtomicInteger maxConcurrent = new AtomicInteger(0);
        AtomicInteger current = new AtomicInteger(0);

        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            var futures = new java.util.ArrayList<Future<?>>();
            for (int i = 0; i < 100; i++) {
                futures.add(executor.submit(() -> {
                    permits.acquire();
                    try {
                        int c = current.incrementAndGet();
                        maxConcurrent.updateAndGet(max -> Math.max(max, c));
                        Thread.sleep(10);  // simulate work
                    } finally {
                        current.decrementAndGet();
                        permits.release();
                    }
                    return null;
                }));
            }
            for (var f : futures) f.get();
        }
        assertThat(maxConcurrent.get()).isLessThanOrEqualTo(5);  // never exceeded 5!
    }
}
