package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.assertThat;

class NoPoolVtTest {

    @Test
    void semaphoreLimitsConcurrencyNotThreads() throws Exception {
        Semaphore dbPermits = new Semaphore(5);   // cap DB concurrency at 5
        AtomicInteger peak = new AtomicInteger();
        AtomicInteger inUse = new AtomicInteger();

        try (ExecutorService vt = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 100; i++) {
                vt.submit(() -> {
                    dbPermits.acquire();
                    try {
                        peak.accumulateAndGet(inUse.incrementAndGet(), Math::max);
                        Thread.sleep(1);
                    } finally { inUse.decrementAndGet(); dbPermits.release(); }
                    return null;
                });
            }
        }
        assertThat(peak.get()).isLessThanOrEqualTo(5);  // never exceeded permits
    }
}
